// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MY_BANK c;
    function setUp() public { c = new MY_BANK(address(new Log())); }

    function testFuzz_property(uint256 t, uint256 amount, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0) && actor != address(c));
        vm.warp(1000);
        t = bound(t, 1001, type(uint256).max - 1);
        amount = bound(amount, 0, 1 ether);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(t);

        assertEq(__invmut_c_Acc_unlockTime(actor), t);
    }

    function __invmut_c_Acc_unlockTime(address __k) internal view returns (uint256) {
        (uint256 _v0, ) = c.Acc(__k);
        return _v0;
    }
}
